xql_query:
// ============================================================
// Rule: O365_Mailbox Rule Creation
// Vendor: Microsoft 365
// Objective:
// Detect activity associated with O365_Mailbox Rule Creation.
// Severity: SEV_040_HIGH
// Category: EXFILTRATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0009 - Collection
// Technique: T1114 - Email Collection
// Technique: T1114.003 - Email Collection: Email Forwarding Rule
// Tactic: TA0010 - Exfiltration

// Fonte de dados: logs brutos do Microsoft 365 Exchange Online
dataset = msft_o365_exchange_online_raw  

// Filtro para identificar a criação de novas regras de transporte (Transport Rules)
// Essas regras podem ser usadas para redirecionar, alterar ou monitorar e-mails.
// A operação "new-transportrule" indica criação de uma nova regra no Exchange.
| filter Operation = "new-transportrule"  

// Seleção dos campos relevantes para análise
| fields USERID,       // Usuário que criou a regra de transporte
         Operation,     // Tipo de operação executada (new-transportrule)
         Parameters     // Parâmetros configurados na regra criada (condições, ações, etc.)
